   104→// test-utils/factories/order-factory.ts
   105→import { createUser } from './user-factory';
   106→import { createProduct } from './product-factory';
   107→
   108→type OrderItem = {
   109→  product: Product;
   110→  quantity: number;
   111→  price: number;
   112→};
   113→
   114→type Order = {
   115→  id: string;
   116→  user: User;
   117→  items: OrderItem[];
   118→  total: number;
   119→  status: 'pending' | 'paid' | 'shipped' | 'delivered';
   120→  createdAt: Date;
   121→};
   122→
   123→export const createOrderItem = (overrides: Partial<OrderItem> = {}): OrderItem => {
   124→  const product = overrides.product || createProduct();
   125→  const quantity = overrides.quantity || faker.number.int({ min: 1, max: 5 });
   126→
   127→  return {
   128→    product,
   129→    quantity,
   130→    price: product.price * quantity,
   131→    ...overrides,
   132→  };
   133→};
