   221→  }
   222→
   223→  return product;
   224→}
   225→
   226→// Playwright globalSetup for shared data
   227→// playwright/support/global-setup.ts
   228→import { chromium, FullConfig } from '@playwright/test';
   229→import { seedUser } from './helpers/seed-helpers';
   230→
   231→async function globalSetup(config: FullConfig) {
   232→  const browser = await chromium.launch();
   233→  const page = await browser.newPage();
   234→  const context = page.context();
   235→
   236→  // Seed admin user for all tests
   237→  const admin = await seedUser(context.request, {
   238→    email: 'admin@example.com',
   239→    role: 'admin',
   240→  });
   241→
   242→  // Save auth state for reuse
   243→  await context.storageState({ path: 'playwright/.auth/admin.json' });
   244→
   245→  await browser.close();
   246→}
   247→
   248→export default globalSetup;
   249→
   250→// Cypress equivalent with cy.task
   251→// cypress/support/tasks.ts
   252→export const seedDatabase = async (entity: string, data: unknown) => {
   253→  // Direct database insert or API call
   254→  if (entity === 'users') {
   255→    await db.users.create(data);
   256→  }
   257→  return null;
   258→};
   259→
   260→// Usage in Cypress tests:
   261→beforeEach(() => {
   262→  const user = createUser({ email: 'test@example.com' });
   263→  cy.task('db:seed', { entity: 'users', data: user });
   264→});
   265→```
   266→
   267→**Key Points**:
   268→
   269→- API seeding is 10-50x faster than UI-based setup
   270→- `globalSetup` seeds shared data once (e.g., admin user)
   271→- Per-test seeding uses `seedUser()` helpers for isolation
   272→- Cypress `cy.task` allows direct database access for speed
   273→
   274→### Example 4: Anti-Pattern - Hardcoded Test Data
   275→
   276→**Problem**:
   277→
   278→```typescript
   279→// ❌ BAD: Hardcoded test data
   280→test('user can login', async ({ page }) => {
   281→  await page.goto('/login');
   282→  await page.fill('[data-testid="email"]', 'test@test.com'); // Hardcoded
   283→  await page.fill('[data-testid="password"]', 'password123'); // Hardcoded
   284→  await page.click('[data-testid="submit"]');
   285→
   286→  // What if this user already exists? Test fails in parallel runs.
   287→  // What if schema adds required fields? Test breaks.
   288→});
   289→
   290→// ❌ BAD: Static JSON fixtures
   291→// fixtures/users.json
   292→{
   293→  "users": [
   294→    { "id": 1, "email": "user1@test.com", "name": "User 1" },
   295→    { "id": 2, "email": "user2@test.com", "name": "User 2" }
   296→  ]
   297→}
   298→
   299→test('admin can delete user', async ({ page }) => {
   300→  const users = require('../fixtures/users.json');
   301→  // Brittle: IDs collide in parallel, schema drift breaks tests
   302→});
   303→```
   304→
   305→**Why It Fails**:
   306→
   307→- **Parallel collisions**: Hardcoded IDs (`id: 1`, `email: 'test@test.com'`) cause failures when tests run concurrently
   308→- **Schema drift**: Adding required fields (`phoneNumber`, `address`) breaks all tests using fixtures
   309→- **Hidden intent**: Does this test need `email: 'test@test.com'` specifically, or any email?
   310→- **Slow setup**: UI-based data creation is 10-50x slower than API
   311→
   312→**Better Approach**: Use factories
   313→
   314→```typescript
   315→// ✅ GOOD: Factory-based data
   316→test('user can login', async ({ page, apiRequest }) => {
   317→  const user = createUser({ email: 'unique@example.com', password: 'secure123' });
   318→
   319→  // Seed via API (fast, parallel-safe)
   320→  await apiRequest({ method: 'POST', url: '/api/users', data: user });
   321→
   322→  // Test UI
   323→  await page.goto('/login');
   324→  await page.fill('[data-testid="email"]', user.email);
   325→  await page.fill('[data-testid="password"]', user.password);
   326→  await page.click('[data-testid="submit"]');
   327→
   328→  await expect(page).toHaveURL('/dashboard');
   329→});
   330→
   331→// ✅ GOOD: Factories adapt to schema changes automatically
   332→// When `phoneNumber` becomes required, update factory once:
   333→export const createUser = (overrides: Partial<User> = {}): User => ({
   334→  id: faker.string.uuid(),
   335→  email: faker.internet.email(),
   336→  name: faker.person.fullName(),
   337→  phoneNumber: faker.phone.number(), // NEW field, all tests get it automatically
   338→  role: 'user',
   339→  ...overrides,
   340→});
   341→```
   342→
   343→**Key Points**:
   344→
   345→- Factories generate unique, parallel-safe data
   346→- Schema evolution handled in one place (factory), not every test
   347→- Test intent explicit via overrides
   348→- API seeding is fast and reliable
   349→
   350→### Example 5: Factory Composition
   351→
   352→**Context**: When building specialized factories, compose simpler factories instead of duplicating logic. Layer overrides for specific test scenarios.
   353→
   354→**Implementation**:
   355→
   356→```typescript
   357→// test-utils/factories/user-factory.ts (base)
   358→export const createUser = (overrides: Partial<User> = {}): User => ({
   359→  id: faker.string.uuid(),
   360→  email: faker.internet.email(),
   361→  name: faker.person.fullName(),
   362→  role: 'user',
   363→  createdAt: new Date(),
   364→  isActive: true,
   365→  ...overrides,
   366→});
   367→
   368→// Compose specialized factories
   369→export const createAdminUser = (overrides: Partial<User> = {}): User => createUser({ role: 'admin', ...overrides });
   370→
   371→export const createModeratorUser = (overrides: Partial<User> = {}): User => createUser({ role: 'moderator', ...overrides });
   372→
   373→export const createInactiveUser = (overrides: Partial<User> = {}): User => createUser({ isActive: false, ...overrides });
   374→
   375→// Account-level factories with feature flags
   376→type Account = {
   377→  id: string;
   378→  owner: User;
   379→  plan: 'free' | 'pro' | 'enterprise';
   380→  features: string[];
   381→  maxUsers: number;
   382→};
   383→
   384→export const createAccount = (overrides: Partial<Account> = {}): Account => ({
   385→  id: faker.string.uuid(),
   386→  owner: overrides.owner || createUser(),
   387→  plan: 'free',
   388→  features: [],
   389→  maxUsers: 1,
   390→  ...overrides,
   391→});
   392→
   393→export const createProAccount = (overrides: Partial<Account> = {}): Account =>
   394→  createAccount({
   395→    plan: 'pro',
   396→    features: ['advanced-analytics', 'priority-support'],
   397→    maxUsers: 10,
   398→    ...overrides,
   399→  });
   400→
   401→export const createEnterpriseAccount = (overrides: Partial<Account> = {}): Account =>
   402→  createAccount({
   403→    plan: 'enterprise',
   404→    features: ['advanced-analytics', 'priority-support', 'sso', 'audit-logs'],
   405→    maxUsers: 100,
   406→    ...overrides,
   407→  });
   408→
   409→// Usage in tests:
   410→test('pro accounts can access analytics', async ({ page, apiRequest }) => {
   411→  const admin = createAdminUser({ email: 'admin@company.com' });
   412→  const account = createProAccount({ owner: admin });
   413→
   414→  await apiRequest({ method: 'POST', url: '/api/users', data: admin });
   415→  await apiRequest({ method: 'POST', url: '/api/accounts', data: account });
   416→
   417→  await page.goto('/analytics');
   418→  await expect(page.getByText('Advanced Analytics')).toBeVisible();
   419→});
   420→
   421→test('free accounts cannot access analytics', async ({ page, apiRequest }) => {
   422→  const user = createUser({ email: 'user@company.com' });
   423→  const account = createAccount({ owner: user }); // Defaults to free plan
   424→
   425→  await apiRequest({ method: 'POST', url: '/api/users', data: user });
   426→  await apiRequest({ method: 'POST', url: '/api/accounts', data: account });
   427→
   428→  await page.goto('/analytics');
   429→  await expect(page.getByText('Upgrade to Pro')).toBeVisible();
   430→});
   431→```
   432→
   433→**Key Points**:
   434→
   435→- Compose specialized factories from base factories (`createAdminUser` → `createUser`)
   436→- Defaults cascade: `createProAccount` sets plan + features automatically
   437→- Still allow overrides: `createProAccount({ maxUsers: 50 })` works
   438→- Test intent clear: `createProAccount()` vs `createAccount({ plan: 'pro', features: [...] })`
   439→
   440→## Integration Points
   441→
   442→- **Used in workflows**: `*atdd` (test generation), `*automate` (test expansion), `*framework` (factory setup)
   443→- **Related fragments**:
   444→  - `fixture-architecture.md` - Pure functions and fixtures for factory integration
   445→  - `network-first.md` - API-first setup patterns
   446→  - `test-quality.md` - Parallel-safe, deterministic test design
   447→
   448→## Cleanup Strategy
   449→
   450→Ensure factories work with cleanup patterns:
   451→
   452→```typescript
   453→// Track created IDs for cleanup
   454→const createdUsers: string[] = [];
   455→
   456→afterEach(async ({ apiRequest }) => {
   457→  // Clean up all users created during test
   458→  for (const userId of createdUsers) {
   459→    await apiRequest({ method: 'DELETE', url: `/api/users/${userId}` });
   460→  }
   461→  createdUsers.length = 0;
   462→});
   463→
   464→test('user registration flow', async ({ page, apiRequest }) => {
   465→  const user = createUser();
   466→  createdUsers.push(user.id);
   467→
   468→  await apiRequest({ method: 'POST', url: '/api/users', data: user });
   469→  // ... test logic
   470→});
   471→```
   472→
   473→## Feature Flag Integration
   474→
   475→When working with feature flags, layer them into factories:
   476→
   477→```typescript
   478→export const createUserWithFlags = (
   479→  overrides: Partial<User> = {},
   480→  flags: Record<string, boolean> = {},
   481→): User & { flags: Record<string, boolean> } => ({
   482→  ...createUser(overrides),
   483→  flags: {
   484→    'new-dashboard': false,
   485→    'beta-features': false,
   486→    ...flags,
   487→  },
   488→});
